    @Override
    @Transactional
    public void saveOwner(Owner owner) throws DataAccessException {
        ownerRepository.save(owner);

    }

    @Override
    @Transactional
    public void createOwner(Owner owner) throws DataAccessException {
        rejectWhenDailyLimitReached(owner);
        rejectWhenCityAtCapacity(owner);
        rejectWhenDuplicateIdentity(owner);
        owner.setHouseholdId(deriveHouseholdId(owner));
        List<Owner> householdMembers = findHouseholdMembers(owner);
        assignPossibleDuplicate(owner);
        owner.setHouseholdMemberCount(householdMembers.size() + 1);
        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
        if (owner.getMemberId() == null) {
            owner.setMemberId(deduplicateMemberId(deriveMemberId(owner)));
        }
        if (owner.getNamesakeCount() == null) {
            owner.setNamesakeCount(countNamesakes(owner));
        }
        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
        owner.setCapacityWarning(approachingCityCapacity(owner));
        ownerRepository.save(owner);
    }

    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;

    /**
     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
     * reflects the owners present at creation time. The new owner's registration date, defaulted to
     * today by the controller, determines which day is counted — the same accumulation path as the
     * daily-limit rule.
     */
    private boolean exceedsBulkSignupThreshold(Owner owner) {
        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
    }

    /**
     * Count the existing owners that already share this owner's first name and last name,
     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
     * before the owner is persisted, so it reflects the owners present at creation time.
     */
    private int countNamesakes(Owner owner) {
        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
        String lastName = IdentityNormalizer.normalize(owner.getLastName());
        return (int) findActiveOwners().stream()
            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
            .count();
    }

    /**
     * The existing owners that have not been soft-deleted. Duplicate and identity checks run
     * against this set, so an owner flagged {@code deleted} (see {@link #deleteOwner(Owner)}) is
     * ignored and no longer blocks a create that would otherwise match it.
     */
    private List<Owner> findActiveOwners() {
        return ownerRepository.findAll().stream()
            .filter(existing -> !existing.isDeleted())
            .toList();
    }

    /**
     * The existing owners that already belong to this owner's household, i.e. those carrying the
     * same deterministic {@code householdId} (see {@link #deriveHouseholdId(Owner)}). Because the
     * household id is derived purely from the normalized last name and postcode, this is exactly
     * the set of owners sharing that last name and postcode. Evaluated before the owner is
     * persisted, so it reflects the owners present at creation time. The owner's own
     * {@code householdId} must already be assigned before calling.
     */
    private List<Owner> findHouseholdMembers(Owner owner) {
        String householdId = owner.getHouseholdId();
        return findActiveOwners().stream()
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .toList();
    }

    /**
     * Derive the owner's deterministic household identifier: the first twelve hexadecimal characters
     * of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two owners with the
     * same last name (compared case-insensitively with collapsed whitespace) and postcode therefore
     * map to the same value automatically, without any opt-in, so they form one household.
     */
    private static String deriveHouseholdId(Owner owner) {
        String lastName = IdentityNormalizer.normalize(owner.getLastName());
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        return sha256HexPrefix(lastName + "|" + postcode, 12);
    }

    /**
     * The membership-level ceiling for a new owner joining {@code householdMembers}: one above the
     * maximum membership level among the existing members. Returns {@code null} when the household
     * has no existing member, so no cap applies. Evaluated before the owner is persisted, so it
     * reflects the members (and their levels) present at creation time.
     */
    private Integer membershipLevelCap(List<Owner> householdMembers) {
        return householdMembers.stream()
            .map(MembershipLevels::level)
            .max(Integer::compareTo)
            .map(max -> max + 1)
            .orElse(null);
    }

    /**
     * Reject the create with a {@code 409 Conflict} when the owner's derived {@code identityKey}
     * (see {@link IdentityKeyNormalizer}) exactly matches that of an existing, non-deleted owner.
     * This single key is the whole of duplicate detection: the former separate household-duplicate
     * block from the computed {@code householdId} no longer applies. Owners flagged {@code deleted}
     * are ignored (see {@link #findActiveOwners()}); the e-mail-domain blocklist is applied earlier,
     * before this method runs. Evaluated before the owner is persisted, so it reflects the owners
     * present at creation time.
     */
    private void rejectWhenDuplicateIdentity(Owner owner) {
        String identityKey = IdentityKeyNormalizer.derive(owner);
        boolean duplicate = findActiveOwners().stream()
            .anyMatch(existing -> identityKey.equals(IdentityKeyNormalizer.derive(existing)));
        if (duplicate) {
            throw new DuplicateIdentityException(
                "an owner with the same identity key already exists");
        }
    }

    /**
     * Set the new owner's soft-duplicate flags. Because the telephone is part of the
     * {@code identityKey}, two owners sharing a last name and postcode but with different telephones
     * are no longer a hard duplicate; they are surfaced as a soft match instead. The flag is raised
     * when the owner's {@code identityKey} differs from an existing, non-deleted owner's yet their
     * last-name {@link Soundex} codes and postcodes match, pointing {@code possibleDuplicateOf} at
     * that owner; otherwise both flags are cleared so the field is always present in the response.
     * Evaluated before the owner is persisted, so it reflects the owners present at creation time.
     */
    private void assignPossibleDuplicate(Owner owner) {
        String identityKey = IdentityKeyNormalizer.derive(owner);
        String soundex = Soundex.encode(owner.getLastName());
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        Owner match = findActiveOwners().stream()
            .filter(existing -> !identityKey.equals(IdentityKeyNormalizer.derive(existing)))
            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
            .filter(existing -> postcode.equals(existing.getPostcode() == null ? "" : existing.getPostcode()))
            .findFirst()
            .orElse(null);
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
        else {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
        }
    }

    /** Maximum number of owners that may be created on any single day (by registration date). */
    private static final long DAILY_OWNER_LIMIT = 100L;

    /**
     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
     * reflects the owners present at creation time. The new owner's own registration date, defaulted
     * to today by the controller, determines which day the limit is checked against.
     */
    private void rejectWhenDailyLimitReached(Owner owner) {
        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
            throw new DailyOwnerLimitExceededException(
                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
        }
    }

    /**
     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
     * before the owner is persisted, so it reflects the owners present at creation time.
     */
    private long countOwnersRegisteredOn(LocalDate day) {
        return ownerRepository.findAll().stream()
            .filter(existing -> day.equals(existing.getRegistrationDate()))
            .count();
    }

    /** Maximum number of owners allowed to live in any single city. */
    private static final long CITY_CAPACITY = 50L;

    /**
     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
     * is persisted, so it reflects the owners present at creation time.
     */
    private void rejectWhenCityAtCapacity(Owner owner) {
        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
            throw new CityCapacityExceededException(
                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
        }
    }

    /**
     * Lower bound (inclusive) of the range of existing owners in a city that raises the
     * capacity warning. Between this and {@code CITY_CAPACITY - 1} the city is approaching its
     * {@value #CITY_CAPACITY} limit.
     */
    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;

    /**
     * Whether the owner's city already contains between {@value #CITY_CAPACITY_WARNING_THRESHOLD}
     * and {@code CITY_CAPACITY - 1} owners (approaching, but not at, the {@value #CITY_CAPACITY}
     * capacity limit), compared case-insensitively with collapsed whitespace. Evaluated before the
     * owner is persisted, so it reflects the owners present at creation time. The hard rejection at
     * {@value #CITY_CAPACITY} runs earlier (see {@link #rejectWhenCityAtCapacity(Owner)}), so the
     * count is always below capacity when this is reached.
     */
    private boolean approachingCityCapacity(Owner owner) {
        long count = countOwnersInCity(owner);
        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
    }

    /**
     * Count the existing owners that already live in this owner's city, compared
     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
     * owner is persisted, so it reflects the owners present at creation time.
     */
    private long countOwnersInCity(Owner owner) {
        String city = IdentityNormalizer.normalize(owner.getCity());
        return ownerRepository.findAll().stream()
            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
            .count();
    }

    /**
     * Builds the member id {@code '<REGION><FY><HASH8><CHK>'}: the region code derived from the
     * owner's postcode, the two-digit fiscal year derived from the (business-day-adjusted)
     * registrationDate, the first eight upper-case hexadecimal characters of the SHA-256 digest over
     * the owner's normalized (E.164) telephone concatenated with the last name (the same HASH8 used
     * by the region-and-hash identity), and a single Luhn check digit computed over the digits of
     * {@code <REGION><FY><HASH8>}. No sequence number is used; the identity is fully derived from the
     * region, fiscal year and hash.
     */
    private String deriveMemberId(Owner owner) {
        String region = Regions.forPostcode(owner.getPostcode());
        LocalDate registrationDate = owner.getRegistrationDate() != null
            ? owner.getRegistrationDate() : LocalDate.now();
        String fiscalYear = RegistrationDateNormalizer.fiscalYearYY(registrationDate);
        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        String base = region + fiscalYear + sha256Hex8(telephone + lastName);
        return base + luhnCheckDigit(base);
    }

    /**
     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value};
     * non-digit characters are ignored.
     */
    private static int luhnCheckDigit(String value) {
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * De-duplicates a computed {@code memberId} against the existing owners: if no owner already
     * carries {@code baseId} it is returned unchanged, otherwise {@code '-<n>'} is appended with the
     * smallest {@code n} of 2 or more that yields a value no existing owner holds. Evaluated before the
     * owner is persisted, so it reflects the owners present at creation time.
     */
    private String deduplicateMemberId(String baseId) {
        Set<String> existingIds = findActiveOwners().stream()
            .map(Owner::getMemberId)
            .filter(Objects::nonNull)
            .collect(Collectors.toSet());
        if (!existingIds.contains(baseId)) {
            return baseId;
        }
        int n = 2;
        while (existingIds.contains(baseId + "-" + n)) {
            n++;
        }
        return baseId + "-" + n;
    }

    /**
     * Returns the region code whose inclusive postcode range contains {@code postcode}
     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
     */
    private static String regionForPostcode(String postcode) {
        if (postcode == null || !postcode.matches("\\d{4}")) {
            return UNKNOWN_REGION;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return UNKNOWN_REGION;
    }

    /**
     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
     * SHA-256 digest of the UTF-8 bytes of {@code value}.
     */
    private static String sha256Hex8(String value) {
        return sha256HexPrefix(value, 8).toUpperCase();
    }

    /**
     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
     * the UTF-8 bytes of {@code value}.
     */
    private static String sha256HexPrefix(String value, int hexChars) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(hexChars);
            for (int i = 0; sb.length() < hexChars; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.substring(0, hexChars);
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 is required but unavailable", e);
        }
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
        return ownerRepository.findByLastName(lastName);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Visit> findVisitsByPetId(int petId) {
        return visitRepository.findByPetId(petId);
    }

    @Override
    @Transactional(readOnly = true)
    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
    }

    private <T> T findEntityById(Supplier<T> supplier) {
        try {
            return supplier.get();
        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
            // Just ignore not found exceptions for Jdbc/Jpa realization
            return null;
        }
    }

}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.service.MembershipLevels;
import org.springframework.samples.petclinic.rest.validation.IdentityKeyNormalizer;
import org.springframework.samples.petclinic.rest.validation.RegistrationDateNormalizer;
import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;

import java.time.LocalDate;
import java.time.Period;
import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName", expression = "java(displayName(owner))")
    @Mapping(target = "salutation", expression = "java(salutation(owner))")
    @Mapping(target = "initials", expression = "java(initials(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "timezone", expression = "java(timezone(owner))")
    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
    @Mapping(target = "capacityWarning", expression = "java(capacityWarning(owner))")
    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    /**
     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
     */
    default String displayName(Owner owner) {
        if (owner == null) {
            return null;
        }
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
        return lastName + ", " + firstName;
    }

    /**
     * Composes the owner's salutation as {@code '<title> <lastName>'} — the title, a single
     * space and the last name — or just the last name when no (blank/absent) title is given.
     */
    default String salutation(Owner owner) {
        if (owner == null) {
            return null;
        }
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        String title = owner.getTitle();
        if (title == null || title.isBlank()) {
            return lastName;
        }
        return title + " " + lastName;
    }

    /**
     * Returns the upper-cased first letters of firstName and lastName,
     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
     */
    default String initials(Owner owner) {
        if (owner == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        if (firstName != null && !firstName.isEmpty()) {
            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
        }
        if (lastName != null && !lastName.isEmpty()) {
            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
        }
        return sb.toString();
    }

    /**
     * Formats the owner's stored E.164 {@code telephone} for human display: the country code,
     * a space, and the national digits grouped in threes separated by spaces, e.g.
     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw {@code telephone} is
     * left unchanged in E.164 form.
     */
    default String telephoneDisplay(Owner owner) {
        if (owner == null) {
            return null;
        }
        return TelephoneNormalizer.toDisplay(owner.getTelephone());
    }

    /**
     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}: the literal {@code 'FY'}
     * and the last two digits of the fiscal year derived from the (business-day-adjusted)
     * registrationDate. The fiscal year starts on 1 July. Returns {@code null} when no registration
     * date is present.
     */
    default String fiscalYear(Owner owner) {
        if (owner == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return "FY" + fiscalYearYY(owner.getRegistrationDate());
    }

    /**
     * Formats the last two digits (zero-padded) of the fiscal year that {@code date} falls in.
     */
    private String fiscalYearYY(LocalDate date) {
        return String.format("%02d", RegistrationDateNormalizer.fiscalYear(date) % 100);
    }

    /**
     * The owner's membership points; see {@link MembershipLevels#points(Owner)}.
     */
    default Integer membershipPoints(Owner owner) {
        return MembershipLevels.points(owner);
    }

    /**
     * The owner's capped numeric membership level; see {@link MembershipLevels#level(Owner)}.
     */
    default Integer membershipLevel(Owner owner) {
        return MembershipLevels.level(owner);
    }

    /** The region codes that can prefix a {@code memberId}. */
    java.util.List<String> REGIONS = java.util.List.of("NSW", "VIC", "QLD", "UNKNOWN");

    /**
     * Derives the owner's locality (region) from the {@code memberId}, whose form is
     * {@code '<REGION><FY><HASH8><CHK>'}: the locality is the {@code REGION} prefix. Returns
     * {@code "UNKNOWN"} when the owner has no member id yet, or when the prefix is not a known region.
     */
    default String locality(Owner owner) {
        if (owner == null) {
            return null;
        }
        String memberId = owner.getMemberId();
        if (memberId == null) {
            return "UNKNOWN";
        }
        for (String region : REGIONS) {
            if (memberId.startsWith(region)) {
                return region;
            }
        }
        return "UNKNOWN";
    }

    /**
     * Derives the owner's IANA {@code timezone} from its locality/region using the fixed
     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region is not in the table.
     */
    default String timezone(Owner owner) {
        if (owner == null) {
            return null;
        }
        String region = locality(owner);
        return switch (region) {
            case "NSW" -> "Australia/Sydney";
            case "VIC" -> "Australia/Melbourne";
            case "QLD" -> "Australia/Brisbane";
            default -> null;
        };
    }

    /**
     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
     * on its registration day at creation time). A {@code null} stored value is treated as
     * {@code false}, so the field is always present in the response.
     */
    default Boolean bulkSignupWarning(Owner owner) {
        if (owner == null) {
            return null;
        }
        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
    }

    /**
     * Whether the owner carries the capacity warning (its city already held between 40 and 49
     * owners, approaching the capacity limit of 50, at creation time). A {@code null} stored value
     * is treated as {@code false}, so the field is always present in the response.
     */
    default Boolean capacityWarning(Owner owner) {
        if (owner == null) {
            return null;
        }
        return Boolean.TRUE.equals(owner.getCapacityWarning());
    }

    /**
     * Whether the owner was flagged as a possible (soft) duplicate at creation time — not a hard
     * duplicate, but sharing an existing owner's last-name Soundex code and postcode while differing
     * on the identity key (typically a different telephone). A {@code null} stored value is treated
     * as {@code false}, so the field is always present in the response.
     */
    default Boolean possibleDuplicate(Owner owner) {
        if (owner == null) {
            return null;
        }
        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
    }

    /**
     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
     * present, otherwise {@code PHONE}.
     */
    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
        if (owner == null) {
            return null;
        }
        String email = owner.getEmail();
        return (email != null && !email.isEmpty())
            ? OwnerDto.ContactPreferenceEnum.EMAIL
            : OwnerDto.ContactPreferenceEnum.PHONE;
    }

    /**
     * Derives the owner's {@code identityKey}, the single value into which duplicate detection is
     * consolidated: the SHA-256 hex over
     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
     */
    default String identityKey(Owner owner) {
        return IdentityKeyNormalizer.derive(owner);
    }

    /**
     * Derives the owner's {@code ageBand} from {@code birthDate}, measured as of the owner's
     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and
     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date is known (or when
     * no reference registration date is available), so the field is absent from the response.
     */
    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
        if (owner == null || owner.getBirthDate() == null) {
            return null;
        }
        LocalDate reference = owner.getRegistrationDate();
        if (reference == null) {
            reference = LocalDate.now();
        }
        int age = Period.between(owner.getBirthDate(), reference).getYears();
        if (age < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
        if (age < 65) {
            return OwnerDto.AgeBandEnum.ADULT;
        }
        return OwnerDto.AgeBandEnum.SENIOR;
    }

    /**
     * Derives the owner's {@code selfLink}, the canonical API path for the owner, formed as
     * {@code '/api/owners/'} followed by the owner's id. Returns {@code null} until the owner
     * has an id, so the field is absent from the response.
     */
    default String selfLink(Owner owner) {
        if (owner == null || owner.getId() == null) {
            return null;
        }
        return "/api/owners/" + owner.getId();
    }

    /**
     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
     * {@code PREMIUM} when {@link #membershipLevel(Owner)} is 3 or more, otherwise {@code STANDARD}.
     * AREA is {@code METRO} when {@link #locality(Owner)} is a known region (NSW, VIC or QLD),
     * otherwise {@code REGIONAL}.
     */
    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
        if (owner == null) {
            return null;
        }
        Integer level = membershipLevel(owner);
        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
        String region = locality(owner);
        boolean metro = "NSW".equals(region) || "VIC".equals(region) || "QLD".equals(region);
        String area = metro ? "METRO" : "REGIONAL";
        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
    }

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

